payload.arguments:
{"command":"$rgConfig = Join-Path $HOME '.ripgreprc'
if (!(Test-Path $rgConfig)) {
  Set-Content -Path $rgConfig -Value @('--follow') -Encoding ASCII
} else {
  $content = Get-Content -Path $rgConfig
  if ($content -notcontains '--follow') {
    Add-Content -Path $rgConfig -Value '--follow' -Encoding ASCII
  }
}
# Set user env var for future sessions
setx RIPGREP_CONFIG_PATH "$rgConfig" | Out-Null
# Ensure PowerShell profile sets it for current sessions too
$profilePath = $PROFILE
if (!(Test-Path $profilePath)) {
  New-Item -ItemType File -Path $profilePath -Force | Out-Null
}
$profileContent = Get-Content -Path $profilePath
$line = "if (-not $env:RIPGREP_CONFIG_PATH) { $env:RIPGREP_CONFIG_PATH = '$rgConfig' }"
if ($profileContent -notcontains $line) {
  Add-Content -Path $profilePath -Value $line -Encoding ASCII
}
$rgConfig","workdir":"e:\PVE"}

